contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(address newOwner) public payable {
        require(newOwner != address(0));

        // Read initial owner
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;

        // Attempt to transfer ownership as this contract (msg.sender == address(this))
        bool reverted;
        c.transferOwnership(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read owner after attempt
        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;

        // General invariant:
        // - If the call did not revert, then this contract must have been the owner before the call, and owner became newOwner.
        // - If the call reverted, then either this contract was not the owner (so owner stayed as beforeOwner), or revert prevented change.
        // We express this as a single assertion combining these facts.
        assert((!reverted && beforeOwner == address(this) && afterOwner == newOwner) || (reverted && afterOwner == beforeOwner));
    }

    receive() external payable { }
}

