contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address newOwner) internal {
        vm.assume(newOwner != address(0));
        address beforeOwner;
        try c.owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address afterOwner;
        try c.owner() returns (address __r) { afterOwner = __r; } catch { return; }
        assertTrue((!reverted && beforeOwner == address(this) && afterOwner == newOwner) || (reverted && afterOwner == beforeOwner));
    }

    function testFuzz_run(address newOwner) public {
